function kb.xpRate()
local fbb=N.session()
if not fbb then
return 0
end
local gbb=0
for hbb,ibb in ipairs(kb.core())do
local jbb=fbb.collection:get_unit_by_uuid(ibb)
if jbb then
local kbb,lbb=kb.gainXp(jbb,500000)
if lbb>0 then
gbb=math.max(gbb,kbb/lbb)
end
end
end
local mbb=gbb*(O.strengthValue or 300)
if(tonumber(N.cur(aje[2057]))or 0)>(O.xpGoldFloor or 100000)then
mbb=math.min(mbb,(N.GOLD_VALUE or 0.02)/14)
end
