function kb.xpGuess(nbb)
local obb=nbb.level and N.Levels[nbb.level]
if not obb then
return 0
end
local pbb=math.min(9,tonumber(obb.story_world_rank)or tonumber(nbb.rank)or 9)
local qbb=tonumber(obb.story_level_rank)or 6
local rbb=(nbb.kind==aje[2031]and 1.5 or 1)*(pbb>5 and 2 or 1)
local sbb=2.1564^(pbb-1)*(40+10*qbb)/rbb
if nbb.kind==aje[2010]then
sbb=3*30*2.1564^(pbb-1)/rbb
end
local tbb=pbb>=9 and 0.3 or(pbb>=7 and 0.5 or 1)
return sbb*tbb*6
end
function kb.modeBonus(ubb)
if not(O.team and O.teamXp)or ubb.kind==aje[2011]or ubb.kind==aje[2008]then
return 0
end
local vbb=kb._xpRate and os.time()-(kb._xpRateAt or 0)<300 and kb._xpRate or nil
if not vbb then
vbb=kb.xpRate()
kb._xpRate,kb._xpRateAt=vbb,os.time()
end
if vbb<=0 then
return 0
end
local wbb=P.modes and P.modes[ubb.key]
local xbb=tonumber(wbb and wbb.xp)or kb.xpGuess(ubb)
local ybb=xbb*vbb
if ybb<1 then
return 0
end
return ybb,string.format(aje[3018],U.fmt(xbb),math.floor(ybb+0.5))
end
