function kb.feedPlan(Ibb)
local Jbb=V.trait(Ibb)
local Kbb=Jbb==aje[3020]and 1.5 or 1
local Lbb=math.max(0,kb.xpFor(Ibb.unit_id,kb.cap(Ibb))-(tonumber(Ibb.xp)or 0))
local Mbb,Nbb,Obb={},0,0
for Pbb,Qbb in ipairs(kb.foodHeld())do
local Rbb=Qbb.xp*Kbb
local Sbb=math.min(Qbb.n,math.floor((Lbb-Nbb)/math.max(1,Rbb)))
if Sbb>0 then
Mbb[Qbb.id]=Sbb
Nbb=Nbb+Sbb*Rbb
Obb=Obb+Sbb
end
end
return{feed=Mbb,planned=Nbb,n=Obb}
end
function kb.run(Tbb)
local Ubb=N.session()
local Vbb=Ubb and Ubb.collection:get_unit_by_uuid(Tbb.uuid)
if not Vbb then
return
end
if Tbb.kind==aje[3014]then
local Wbb=kb.feedPlan(Vbb)
local Xbb,Ybb,Zbb=Wbb.feed,Wbb.planned,Wbb.n
if Zbb==0 then
P.str.feedNote=Tbb.name..aje[3021]
return
end
local _bb,acb=tonumber(Vbb.xp)or 0,kb.level(Vbb)
local bcb,ccb=F.request(aje[3014],aje[3022],Tbb.uuid,Xbb)
local dcb=U.now()
while U.now()-dcb<4 and(tonumber((Ubb.collection:get_unit_by_uuid(Tbb.uuid)or Vbb).xp)or 0)<=_bb do
task.wait(0.25)
end
local ecb=Ubb.collection:get_unit_by_uuid(Tbb.uuid)or Vbb
local fcb=(tonumber(ecb.xp)or 0)-_bb
if fcb>0 then
local gcb=kb.level(ecb)
local hcb=gcb>acb and string.format(aje[3016],acb,gcb)or string.format(aje[3017],acb)
cb.add(string.format(aje[3023],Zbb,Tbb.name),Zbb,aje[3024],string.format(aje[3025],U.fmt(fcb),hcb))
kb.note(string.format(aje[3026],Tbb.name,Zbb,U.fmt(fcb),hcb,math.abs(fcb-Ybb)>Ybb*0.1 and string.format(aje[3027],U.fmt(Ybb))or aje[912]))
else
kb.note(string.format(aje[3028],Tbb.name,tostring(bcb and ccb or aje[2525])))
F.backoff(aje[3014],600)
end
end
end
