cb.add(string.format(aje[3120],#Nfb,Bfb),#Nfb,aje[3121],string.format(aje[3122],U.fmt(Tfb-Pfb)))
F.log(1,aje[2495],string.format(aje[3123],#Nfb,Bfb,U.fmt(Tfb-Pfb),kb.level(zfb.collection:get_unit_by_uuid(O.fuseXpUnit)or Afb)))
