local Wfb=F.gameSaid(Qfb)
ab.pickNote.autoFuseXp=aje[3125]..tostring(Wfb or(Rfb and Sfb)or aje[2525])..aje[3126]
F.log(1,aje[2495],aje[3127]..tostring(Wfb or(Rfb and Sfb)or aje[2525]))
F.backoff(aje[3118],1800)
break
end
end
end
