for fib,gib in ipairs(W.lastScored or{})do
if gib.kind==aje[2010]and ib.eligible(gib)then
local hib,iib=P.train.real[gib.key],gib.rec or W.rec(gib.key)
local jib=(tonumber(iib.timed)or 0)>0 and iib.sec/iib.timed/60 or 0
local kib=(hib and hib.n>0 and jib>0)and(hib.sum/hib.n)/jib or 0
if kib<=0 then
kib=db.hiveTrainRate(gib.key)or 0
end
if kib>(eib or 0)then
dib,eib=gib,kib
end
end
end
return dib
end
function ib.ratio()
local lib=P.train.cal
if not(lib and(lib.n or 0)>0 and(lib.sim or 0)>0)then
return 1
end
return U.clamp(lib.real/lib.sim,0.05,2)
