local Fib=(tonumber((P.simCal[zib.key]or{}).n)or 0)>0
local Gib=Fib and 1.3 or 2
local Hib=Eib..aje[2305]..Aib.uuid..(Fib and aje[3184]or aje[3185])..aje[3186]
local Iib=P.trainSim[zib.key]
if Iib and Iib.sig==Hib and not Iib.pending and os.time()-(Iib.at or 0)<6*3600 then
