local roc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not roc then
return
end
for soc,toc in pairs(roc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[soc.Name])then
local uoc={}
for voc,woc in ipairs(toc.points or{})do
table.insert(uoc,woc.part.Position)
end
local xoc=0
for yoc=2,#uoc do
xoc=xoc+(uoc[yoc]-uoc[yoc-1]).Magnitude
end
local zoc=0
for Aoc=2,#uoc do
local Boc,Coc=uoc[Aoc-1],uoc[Aoc]
local Doc=(Coc-Boc).Magnitude
local Eoc=math.max(1,math.floor(Doc/2))
for Foc=0,Eoc-1 do
local Goc=Boc:Lerp(Coc,Foc/Eoc)
table.insert(bb.samples,{pos=Goc,prog=(zoc+Doc*Foc/Eoc)/math.max(1,xoc),lane=soc.Name})
end
zoc=zoc+Doc
end
if uoc[#uoc]then
table.insert(bb.samples,{pos=uoc[#uoc],prog=1,lane=soc.Name})
end
end
end
pcall(bb.readHidden,roc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local Hoc=tonumber(bb.ld and bb.ld._portal_lanes)
local Ioc=gb.laneList(bb.samples)
if Hoc and Hoc>=1 and Ioc and#Ioc>Hoc then
