function bb.readHidden(Joc)
local Koc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(Koc)~=aje[1991]or not next(Koc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local Loc
for Moc,Noc in pairs(Joc)do
if Koc[Moc.Name]and type(Noc.points)==aje[1991]and#Noc.points>=2 then
local Ooc={}
for Poc,Qoc in ipairs(Noc.points)do
Ooc[Poc]=U.flat(Qoc.part.Position)
end
local Roc={}
for Soc,Toc in ipairs(bb.samples)do
local Uoc=tostring(Toc.lane)
Roc[Uoc]=Roc[Uoc]or{}
table.insert(Roc[Uoc],Toc)
end
local Voc,Woc
for Xoc,Yoc in pairs(Roc)do
local Zoc=0
for _oc=1,#Ooc,math.max(1,math.floor(#Ooc/20))do
local apc=math.huge
for bpc,cpc in ipairs(Yoc)do
local dpc=(U.flat(cpc.pos)-Ooc[_oc]).Magnitude
if dpc<apc then
apc=dpc
end
end
Zoc=Zoc+apc
end
if not Woc or Zoc<Woc then
Voc,Woc=Xoc,Zoc
end
end
local epc,fpc,gpc,hpc,ipc,jpc={},nil,nil,nil,0,0
for kpc,lpc in ipairs(Ooc)do
local mpc,npc=nil,math.huge
for opc,ppc in ipairs(Roc[Voc])do
local qpc=(U.flat(ppc.pos)-lpc).Magnitude
if qpc<npc then
npc,mpc=qpc,ppc.prog
end
end
jpc=math.max(jpc,npc)
if gpc then
local rpc=mpc-gpc
local spc=(rpc>0.002 and 1)or(rpc< -0.002 and-1)or hpc
if hpc and spc and spc~=hpc then
table.insert(epc,math.floor(gpc*1000+0.5)/1000)
end
hpc,ipc=spc or hpc,ipc+math.abs(rpc)
else
fpc=mpc
end
gpc=mpc
if kpc%50==0 then
task.wait()
end
end
if gpc and jpc<=8 then
table.insert(epc,math.floor(gpc*1000+0.5)/1000)
Loc=Loc or{}
Loc[Moc.Name]={from=math.floor((fpc or 0)*1000+0.5)/1000,len=math.floor(ipc*1000+0.5)/1000,turns=epc,road=Voc}
end
end
end
if not Loc then
return
end
local tpc=bb.ld.map
P.maps[tpc]=P.maps[tpc]or{}
local upc=P.maps[tpc].hidden
P.maps[tpc].hidden=Loc
if type(upc)~=aje[1991]then
for vpc,wpc in pairs(Loc)do
F.log(1,aje[2659],string.format(aje[4039],vpc,wpc.len,tostring(wpc.road),math.floor((#wpc.turns-1)/2)))
end
F.saveSoon()
end
end
function bb.countLanes()
local xpc,ypc,zpc={},0,0
for Apc,Bpc in ipairs(bb.samples)do
local Cpc=tostring(Bpc.lane)
if not xpc[Cpc]then
ypc=ypc+1
end
xpc[Cpc]=(xpc[Cpc]or 0)+1
zpc=zpc+1
end
bb.laneCount={n=ypc,by=xpc,avg=ypc>0 and zpc/ypc or 1}
if ypc>=2 then
local Dpc,Epc=pcall(gb.laneSep,bb.samples)
local Fpc=P.maps[bb.mapKey()]
if Dpc and Epc and type(Fpc)==aje[1991]then
Fpc.sep=Epc
