bb.LANE_WAIT=3
function bb.portalLanes()
if not bb.laneWant or bb.laneCut then
return true
end
if bb.planning then
return false
end
local Gpc,Hpc={},0
for Ipc,Jpc in ipairs(workspace._UNITS:GetChildren())do
local Kpc=Jpc:FindFirstChild(aje[2054])
if Kpc and Kpc:FindFirstChild(aje[4040])and Kpc.player.Value==nil and Kpc:FindFirstChild(aje[4041])and Jpc:FindFirstChild(aje[3239])then
local Lpc=tostring(Kpc.lane.Value)
if not Gpc[Lpc]then
Gpc[Lpc]=true
Hpc=Hpc+1
end
