function bb.infStop(hqc)
local iqc=0
for jqc,kqc in ipairs(U.list(N.GS.DAILY_INFINITE_REWARDS))do
iqc=math.max(iqc,tonumber(kqc.wave)or 0)
end
if iqc<=0 or hqc<=iqc+1 then
return
end
local lqc=P.train.on
if bb.trainee and lqc and lqc.have+(lqc.got or 0)+(bb.trainTk or 0)<lqc.need then
