if hqc>=(oqc.cap+oqc.less)/oqc.per then
pqc=0
else
local qqc=bb.infWaveAt or{}
local rqc,sqc=qqc[hqc],qqc[hqc-5]
if rqc and sqc and rqc>sqc then
pqc=oqc.per*5/((rqc-sqc)/60)
end
if not pqc then
pqc=(nqc>0 and(mqc.sec or 0)>0)and math.max(0.5,(mqc.gems or 0)/(mqc.sec/60))or 2.5
end
end
