for vqc,wqc in ipairs(tqc and W.lastScored or{})do
if wqc.kind~=aje[2010]and(not uqc or(wqc.score or 0)>(uqc.score or 0))then
uqc=wqc
end
end
if not uqc or(uqc.score or 0)<=pqc then
