function bb.valid(Esc,Fsc,Gsc)
local Hsc=N.PC.raycast(Esc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not Hsc then
return nil
end
if not N.PC.is_valid_raycast_hit(Hsc.Instance,Fsc)then
