end
local Isc=Hsc.Position
if bb.blockedSpot(Isc)then
return nil
end
local Jsc=(tonumber(Fsc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(Jsc*2,2.5,Jsc*2)
bb.probe.CFrame=CFrame.new(Isc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
local Ksc=U.flat(Isc)
for Lsc,Msc in ipairs(bb.mine or{})do
local Nsc=Msc:FindFirstChild(aje[4075])
local Osc=Nsc and Nsc.Position or Msc:GetPivot().Position
local Psc=Nsc and math.max(Nsc.Size.X,Nsc.Size.Z)/2 or 1.5
if(Ksc-U.flat(Osc)).Magnitude<Jsc+Psc then
return nil
end
end
if not Gsc then
for Qsc,Rsc in ipairs(bb.blockers())do
if(Ksc-Rsc.p).Magnitude<Jsc+Rsc.r then
return nil
end
end
end
return Isc
end
function bb.buildCandidates()
