for sVc,tVc in ipairs(bb.mine or{})do
local uVc=tVc._stats
local vVc=V.rows(uVc.id.Value)
local wVc=vVc and vVc[math.min(uVc.upgrade.Value,vVc.max)]
local xVc=wVc and wVc.atk and V.attackInfo(wVc.atk,wVc.range)
if xVc and((xVc.stun or 0)>0 or(xVc.slowTime or 0)>0)then
rVc=rVc+1
end
end
local yVc,zVc=gb.mask(bb.info.map,V.range(oVc.u,0)*(bb.info.rangeScale or 1)),0
for AVc=1,gb.BINS do
if yVc[AVc]then
zVc=zVc+1
