function bb.buffGain(DVc)
local EVc=V.allyBuff(DVc.id)
if not EVc then
return 0
end
local FVc,GVc,HVc=bb.buffShort(EVc)
local IVc=V.stackCap(EVc.attack)
local JVc,KVc=pcall(V.range,DVc.u,0)
KVc=(JVc and tonumber(KVc)or 15)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local LVc=IVc and O.community and tonumber(EVc.time)and tonumber(HVc)
local function MVc(NVc,OVc)
local PVc=math.floor(NVc*EVc.time/math.max(1,HVc)+0.001)
return math.min(IVc,(1+OVc)^PVc-1)
end
local QVc=0
for RVc,SVc in ipairs(FVc)do
local TVc=0
for UVc,VVc in ipairs(FVc)do
if(VVc.pos-SVc.pos).Magnitude<=KVc then
local WVc=EVc.types[VVc.base]
local XVc=WVc*EVc.uptime
if LVc then
local YVc,ZVc=MVc(VVc.n,WVc),VVc.n+1
while ZVc<VVc.n+6 and MVc(ZVc,WVc)<=YVc+0.001 do
ZVc=ZVc+1
end
XVc=math.max(0,(MVc(ZVc,WVc)-YVc)/(ZVc-VVc.n))
elseif IVc then
XVc=math.max(0,math.min(IVc,(VVc.n+1)*WVc*EVc.uptime)-math.min(IVc,VVc.n*WVc*EVc.uptime))
end
TVc=TVc+VVc.dps*XVc
end
end
QVc=math.max(QVc,TVc)
end
return QVc*(LVc and 1 or 0.7)
end
function bb.buffWanted(_Vc)
