if bb.kind~=aje[2011]or bb.bailed or O.bailOut==false or bb.random or bb.infinite then
return
end
end
local Hbd=tostring(P.dg.room and P.dg.room.seed)
P.dg.bails=type(P.dg.bails)==aje[1991]and P.dg.bails or{}
if not Gbd and(tonumber(P.dg.bails[Hbd])or 0)>=bb.BAIL_MAX then
return
end
local Ibd=workspace:FindFirstChild(aje[4501])and workspace._BASES:FindFirstChild(aje[4040])
local Jbd=Ibd and Ibd:FindFirstChild(aje[4250])and Ibd.base:FindFirstChild(aje[4251])
local Kbd=Jbd and Jbd:FindFirstChildOfClass(aje[2386])
if not Kbd or Kbd.Health<=0 then
return
end
local Lbd={t=U.now(),base=Kbd.Health,baseMax=Kbd.MaxHealth,foes={}}
for Mbd,Nbd in ipairs(bb.enemies or{})do
if Nbd.m then
Lbd.foes[Nbd.m]={hp=tonumber(Nbd.hp)or 0,prog=tonumber(Nbd.prog)or 0}
end
end
bb.baseTrack=bb.baseTrack or{}
local Obd=bb.baseTrack
table.insert(Obd,Lbd)
while#Obd>1 and Lbd.t-Obd[1].t>bb.BASE_WIN+2 do
table.remove(Obd,1)
end
local Pbd,Qbd=bb.baseVerdict(Obd[1],Lbd)
if Gbd then
return Pbd,Qbd,Lbd
end
if not Pbd then
return
end
bb.bailNote(Hbd,aje[4250])
F.log(1,aje[2659],string.format(aje[4502],bb.wave(),tonumber(bb.total)or 0,math.floor(100*Lbd.base/math.max(1,Lbd.baseMax)+0.5),U.fmt(Qbd.loss),math.floor(Qbd.baseTime),U.fmt(Qbd.atEnd),U.fmt(Qbd.rate),Qbd.killTime==math.huge and aje[4503]or(math.floor(Qbd.killTime)..aje[1839])))
pcall(F.saveNow)
F.request(aje[2062],aje[4088])
end
bb.LEAK_WIN,bb.LEAK_SOON,bb.LEAK_MIN,bb.LEAK_MARGIN,bb.LEAK_AHEAD=3,12,3,1.5,6
function bb.leakAhead(Rbd)
local Sbd=0
local Tbd=U.flat(Rbd.pos)
for Ubd,Vbd in ipairs(bb.mine or{})do
local Wbd=Vbd:FindFirstChild(aje[2054])
local Xbd=Wbd and Wbd:FindFirstChild(aje[2368])
local Ybd=Wbd and Wbd:FindFirstChild(aje[2243])
if Xbd and Ybd and not V.isFarm(Xbd.Value)and not V.allyBuff(Xbd.Value)then
local Zbd,_bd=U.flat(Vbd:GetPivot().Position),Ybd.Value
if(not Rbd.fly or bb.canAir(Vbd))and(Zbd-Tbd).Magnitude>_bd then
for acd,bcd in ipairs(bb.samples or{})do
if bcd.prog>Rbd.prog and(U.flat(bcd.pos)-Zbd).Magnitude<=_bd then
Sbd=Sbd+1
break
end
end
end
end
end
return Sbd
end
function bb.leakStep(ccd)
if not ccd then
if bb.kind~=aje[2011]or bb.bailed or O.bailOut==false or bb.random or bb.infinite then
return
end
end
local dcd=tostring(P.dg.room and P.dg.room.seed)
P.dg.bails=type(P.dg.bails)==aje[1991]and P.dg.bails or{}
if not ccd and(tonumber(P.dg.bails[dcd])or 0)>=bb.BAIL_MAX then
return
end
local ecd=workspace:FindFirstChild(aje[4501])and workspace._BASES:FindFirstChild(aje[4040])
local fcd=ecd and ecd:FindFirstChild(aje[4250])and ecd.base:FindFirstChild(aje[4251])
local gcd=fcd and fcd:FindFirstChildOfClass(aje[2386])
if not gcd or gcd.Health<=0 then
return
end
local hcd=(bb.info and tonumber(bb.info.baseRel))or gb.PRIOR.baseRel
local icd=U.now()
bb.leakTrack=bb.leakTrack or{}
local jcd=bb.leakTrack
local kcd,lcd={},nil
for mcd,ncd in ipairs(bb.enemies or{})do
if ncd.m then
kcd[ncd.m]=true
local ocd,pcd=tonumber(ncd.hp)or 0,tonumber(ncd.prog)or 0
local qcd=jcd[ncd.m]
if not qcd then
jcd[ncd.m]={t=icd,hp=ocd,prog=pcd}
else
if icd-qcd.t>=bb.LEAK_WIN then
qcd.pace,qcd.net=(pcd-qcd.prog)/(icd-qcd.t),(qcd.hp-ocd)/(icd-qcd.t)
qcd.t,qcd.hp,qcd.prog=icd,ocd,pcd
end
if qcd.pace and qcd.pace>0 and ocd>0 then
local rcd=(1-pcd)/qcd.pace
local scd=math.max(0,qcd.net or 0)
local tcd=ocd-scd*rcd
if tcd>0 and rcd<=bb.LEAK_SOON and rcd>=bb.LEAK_MIN then
local ucd=ncd.m:FindFirstChildOfClass(aje[2386])
local vcd=gcd.Health/math.max(1,hcd*(ucd and ucd.MaxHealth or ocd))
local wcd=scd>0 and tcd/scd or math.huge
if wcd>vcd*bb.LEAK_MARGIN and(rcd<=bb.LEAK_AHEAD or bb.leakAhead(ncd)==0)and(not lcd or rcd<lcd.left)then
lcd={left=rcd,arriving=tcd,net=scd,baseTime=vcd,hp=ocd}
end
end
end
end
end
end
for xcd in pairs(jcd)do
if not kcd[xcd]then
jcd[xcd]=nil
end
end
if ccd then
return lcd~=nil,lcd
end
if not lcd then
return
end
bb.bailNote(dcd,aje[4495])
F.log(1,aje[2659],string.format(aje[4504],bb.wave(),tonumber(bb.total)or 0,math.floor(lcd.left+0.5),U.fmt(lcd.hp),U.fmt(lcd.arriving),U.fmt(lcd.net),lcd.baseTime))
pcall(F.saveNow)
F.request(aje[2062],aje[4088])
end
bb.FOCUS_MAX=8
bb.coverMax=setmetatable({},{__mode=aje[2376]})
function bb.allPast(ycd)
local zcd={}
for Acd,Bcd in ipairs(bb.mine or{})do
local Ccd=Bcd._stats
local Dcd=Ccd.id.Value
if not V.isFarm(Dcd)and not V.allyBuff(Dcd)and Ccd:FindFirstChild(aje[2243])then
local Ecd=tonumber(Ccd.range.Value)or 0
local Fcd=bb.coverMax[Bcd]
if not(Fcd and Fcd.r==Ecd)then
local Gcd,Hcd=U.flat(Bcd:GetPivot().Position),-1
for Icd,Jcd in ipairs(bb.samples or{})do
if Jcd.prog>Hcd and(U.flat(Jcd.pos)-Gcd).Magnitude<=Ecd then
Hcd=Jcd.prog
end
end
Fcd={r=Ecd,far=Hcd}
bb.coverMax[Bcd]=Fcd
end
table.insert(zcd,{far=Fcd.far,air=bb.canAir(Bcd)})
end
end
if#zcd==0 then
return false
end
for Kcd,Lcd in ipairs(ycd)do
for Mcd,Ncd in ipairs(zcd)do
if(not Lcd.fly or Ncd.air)and Ncd.far>=(tonumber(Lcd.prog)or 0)then
return false
end
end
end
return true
end
function bb.fbTick()
local Ocd=bb.info and bb.info.final
if not(Ocd and Ocd.cfg)then
return
end
local Pcd=type(bb.info.configs)==aje[1991]and bb.info.configs[Ocd.cfg]
local Qcd=type(Pcd)==aje[1991]and Pcd.unit_id or Ocd.cfg
local Rcd
for Scd,Tcd in ipairs(bb.enemies or{})do
local Ucd=Tcd.m and Tcd.m:FindFirstChild(aje[2054])
if Ucd and Ucd:FindFirstChild(aje[2368])and Ucd.id.Value==Qcd then
Rcd=Tcd
break
end
end
local Vcd=bb.fb
if not Rcd then
if Vcd and not Vcd.gone then
Vcd.gone=U.now()
end
return
end
local Wcd=Rcd.m:FindFirstChildOfClass(aje[2386])
local Xcd=(Wcd and Wcd.MaxHealth>0)and Wcd.MaxHealth or Rcd.hp
local Ycd=(N.Units[Qcd]and N.Units[Qcd].name)or Qcd
if not Vcd or Vcd.m~=Rcd.m then
Vcd={m=Rcd.m,id=Qcd,name=Ycd,wave=bb.wave(),t0=U.now(),max=Xcd,low=1,assassin=Ocd.assassin,beatAt=tonumber(Ocd.beatAt)or 0.5,walk=Ocd.walk}
bb.fb=Vcd
if Ocd.assassin then
F.log(1,aje[2659],string.format(aje[4505],Ycd,Vcd.wave,U.fmt(Xcd),math.floor(Vcd.beatAt*100+0.5)))
end
end
Vcd.e=Rcd
Vcd.share=Xcd>0 and Rcd.hp/Xcd or 1
Vcd.low=math.min(Vcd.low,Vcd.share)
local Zcd,_cd=pcall(N.PATH.get_unit_path_progress,Rcd.m)
Vcd.gp=Zcd and tonumber(_cd)or nil
if Vcd.assassin and not Vcd.beaten and Vcd.share<=Vcd.beatAt+0.005 then
Vcd.beaten=U.now()
F.log(1,aje[2659],string.format(aje[4506],Ycd,math.floor(Vcd.share*100+0.5)))
end
if#(bb.enemies or{})==1 and bb.total and bb.wave()>=bb.total then
Vcd.aloneT=Vcd.aloneT or U.now()
Vcd.alone=math.max(Vcd.alone or 0,U.now()-Vcd.aloneT)
else
Vcd.aloneT=nil
end
