return edd and math.floor(edd*1000+0.5)/1000 or nil
end
return{id=cdd.id,wave=cdd.wave,hp=math.floor(cdd.max),left=cdd.gone and 0 or ddd(cdd.share),low=ddd(cdd.low),lane=ddd(cdd.gp),alone=cdd.alone and math.floor(cdd.alone)or nil,sec=math.floor(U.now()-cdd.t0),won=bdd and true or false,assassin=cdd.assassin or nil}
