if fdd and not gdd.gone and(gdd.share or 0)>0 then
hdd.wonAlive=(tonumber(hdd.wonAlive)or 0)+1
hdd.winAt=math.max(tonumber(hdd.winAt)or 0,math.floor((gdd.share or 0)*1000+0.5)/1000)
end
