local Ydd=(1-Add)/Cdd.rate
bb.focusLeft,bb.focusInRange=Ydd,Idd
local Zdd=(zdd and zdd.assassin)and math.max(0,vdd.hp-zdd.beatAt*zdd.max)or vdd.hp
local _dd=Cdd.net and(Cdd.net<=0 or Zdd/Cdd.net>Ydd*0.8)
