function bb.focusSpot(ued)
local ved=bb.focus
local wed=V.range(ued.u,0)*((bb.info and bb.info.rangeScale)or 1)
local xed=U.flat(ved.pos)
local yed,zed
local Aed=0
for Bed,Ced in ipairs(bb.cands)do
if(U.flat(Ced)-xed).Magnitude<=wed then
local Ded=bb.valid(Ced,ued.data)
Aed=Aed+1
if Aed%40==0 then
task.wait()
end
if Ded then
local Eed,Fed=0,U.flat(Ded)
for Ged,Hed in ipairs(bb.hurtSamples())do
if Hed.prog>=ved.prog and(U.flat(Hed.pos)-Fed).Magnitude<=wed then
Eed=Eed+1
end
end
if not zed or Eed>zed then
yed,zed=Ded,Eed
end
end
end
end
return yed,zed or 0
end
function bb.focusGain(Ied)
local Jed=bb.focus
if not Jed then
return 1
end
local Ked=Ied._stats
if not Ked:FindFirstChild(aje[2243])then
return 1
end
local Led,Med=U.flat(Ied:GetPivot().Position),Ked.range.Value
if Jed.fly and not bb.canAir(Ied)then
return 0.02
end
if(Led-U.flat(Jed.pos)).Magnitude<=Med then
return 1
end
return(Led-U.flat(Jed.pos)).Magnitude<=Med*1.5 and 0.3 or 0.02
end
